package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.*;import com.digitalbase.ticketing.enums.ProductStatus;import com.digitalbase.ticketing.enums.TicketStatus;import com.digitalbase.ticketing.exception.DuplicateResourceException; // 👈 အသစ် Import လုပ်ထားပါသည်import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.model.ClientProduct;import com.digitalbase.ticketing.model.Product;import com.digitalbase.ticketing.model.Ticket;import com.digitalbase.ticketing.model.User;import com.digitalbase.ticketing.repository.ClientProductRepository;import com.digitalbase.ticketing.repository.ProductRepository;import com.digitalbase.ticketing.repository.TicketRepository;import com.digitalbase.ticketing.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.List;import java.util.Optional;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class ClientProductServiceImpl implements ClientProductService {    private final ClientProductRepository clientProductRepository;    private final TicketRepository ticketRepository;    private final UserRepository userRepository;    private final ProductRepository productRepository;    @Override    @Transactional    public ClientProductResponse assignProductToClient(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        Instant now = Instant.now();        Instant newStartDate = now;        // ⏱️ Frontend မှ ပို့လိုက်သော သက်တမ်း (ရက်အရေအတွက်) ကို တိုက်ရိုက်ယူမည် (မပို့ပါက 30 ရက် ဟုယူမည်)        long planDurationDays = request.getDurationDays() != null ? request.getDurationDays() : 30;        // 🧠 [Business Logic] အရင် Plan အဟောင်း ရှိ/မရှိ နှင့် သက်တမ်းကုန်/မကုန် စစ်ဆေးခြင်း        Optional<ClientProduct> latestPlan = clientProductRepository.findTopByUserIdAndProductIdOrderByPlanEndDateDesc(user.getId(), product.getId());        if (latestPlan.isPresent()) {            Instant lastEndDate = latestPlan.get().getPlanEndDate();            // ယခင် Plan သည် သက်တမ်းမကုန်သေးပါက (Active ဖြစ်နေပါက)            if (lastEndDate != null && lastEndDate.isAfter(now)) {                newStartDate = lastEndDate; // အသစ်၏ Start Date ကို အဟောင်းကုန်မည့်ရက်မှ စတင်မည်            }        }        // 📅 အသစ်၏ End Date ကို အထက်တွင် ရရှိလာသော Start Date မှစ၍ ပေါင်းထည့်မည်        Instant newEndDate = newStartDate.plus(planDurationDays, java.time.temporal.ChronoUnit.DAYS);        ClientProduct clientProduct = ClientProduct.builder()                .user(user)                .product(product)                .supportPlan(request.getSupportPlan())                .purchasedDate(now)                .planStartDate(newStartDate) // 👈 တွက်ချက်ထားသော Start Date အသစ်                .planEndDate(newEndDate)     // 👈 တွက်ချက်ထားသော End Date အသစ်                .totalMinutes(request.getTotalMinutes())                .availableMinutes(request.getTotalMinutes())                .build();        clientProduct.setStatus(getDynamicStatus(clientProduct));        ClientProduct savedClientProduct = clientProductRepository.save(clientProduct);        return mapToResponse(savedClientProduct);    }    @Override    @Transactional    public ClientProductResponse renewProductPlan(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        Instant now = Instant.now();        Instant newStartDate = now;        // ⏱️ Frontend မှ ပို့လိုက်သော သက်တမ်း (ရက်အရေအတွက်) ကို တိုက်ရိုက်ယူမည် (မပို့ပါက 365 ရက် ဟုယူမည်)        long planDurationDays = request.getDurationDays() != null ? request.getDurationDays() : 365;        // 🔍 Database ထဲမှ ဤ Customer ၏ နောက်ဆုံးဝယ်ထားသော Plan ကို ရှာဖွေခြင်း        Optional<ClientProduct> latestPlan = clientProductRepository.findTopByUserIdAndProductIdOrderByPlanEndDateDesc(user.getId(), product.getId());        if (latestPlan.isPresent()) {            Instant lastEndDate = latestPlan.get().getPlanEndDate();            // 💡 ယခင် Plan သည် သက်တမ်းမကုန်သေးပါက၊ ထိုရက်စွဲကို Start Date အသစ်အဖြစ် သတ်မှတ်မည်            if (lastEndDate != null && lastEndDate.isAfter(now)) {                newStartDate = lastEndDate;            }        }        // 📅 အသစ်ဝယ်လိုက်သော သက်တမ်း (ရက်အရေအတွက်) ကို Start Date အသစ်ပေါ်တွင် ပေါင်းထည့်မည်        Instant newEndDate = newStartDate.plus(planDurationDays, java.time.temporal.ChronoUnit.DAYS);        ClientProduct renewedPlan = ClientProduct.builder()                .user(user)                .product(product)                .supportPlan(request.getSupportPlan())                .purchasedDate(now)                .planStartDate(newStartDate)                .planEndDate(newEndDate)                .totalMinutes(request.getTotalMinutes())                .availableMinutes(request.getTotalMinutes())                .build();        renewedPlan.setStatus(getDynamicStatus(renewedPlan));        ClientProduct savedPlan = clientProductRepository.save(renewedPlan);        return mapToResponse(savedPlan);    }    @Override    @org.springframework.transaction.annotation.Transactional(readOnly = true)    public TopNavResponse getTopNavSummary(String email) {        // 🎯 orElseThrow တွင် ResourceNotFoundException ကို တိကျစွာ ထည့်ထားပါသည်        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> products = clientProductRepository.findAllByUserId(user.getId());        int totalMins = products.stream().mapToInt(p -> p.getTotalMinutes() != null ? p.getTotalMinutes() : 0).sum();        int availableMins = products.stream().mapToInt(p -> p.getAvailableMinutes() != null ? p.getAvailableMinutes() : 0).sum();        int displayAvailableMins = Math.max(0, availableMins);        String headerText = String.format("Available: %dHrs %d Mins/%d Hrs Credit",                displayAvailableMins / 60, displayAvailableMins % 60, totalMins / 60);        return TopNavResponse.builder()                .headerAvailableCreditText(headerText)                .fullName(user.getFullName())                .build();    }    @Override    @org.springframework.transaction.annotation.Transactional(readOnly = true)    public DashboardSummaryResponse getDashboardSummary(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> products = clientProductRepository.findAllByUserId(user.getId());        int totalMins = 0;        int availableMins = 0;        int activeProductCount = 0;        ClientProduct activeProduct = null;        ClientProduct nearestExpiringProduct = null;        for (ClientProduct cp : products) {            totalMins += (cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0);            availableMins += (cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0);            // 👈 cp.getStatus() အစား Dynamic Status ဖြင့် စစ်ဆေးမည်            ProductStatus dynamicStatus = getDynamicStatus(cp);            if (dynamicStatus == ProductStatus.ACTIVE || dynamicStatus == ProductStatus.EXPIRING_SOON) {                activeProductCount++;                if (activeProduct == null) activeProduct = cp;                if (nearestExpiringProduct == null || cp.getPlanEndDate().isBefore(nearestExpiringProduct.getPlanEndDate())) {                    nearestExpiringProduct = cp;                    activeProduct = cp;                }            }        }        int displayAvailableMins = Math.max(0, availableMins);        int usedMinsTotal = Math.max(0, totalMins - displayAvailableMins);        int extraMinsTotal = availableMins < 0 ? Math.abs(availableMins) : 0;        long daysRemaining = 0;        String expiryString = "N/A";        if (nearestExpiringProduct != null && nearestExpiringProduct.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(Instant.now(), nearestExpiringProduct.getPlanEndDate());            if (daysRemaining < 0) daysRemaining = 0;            java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("'Expired in' MMM d")                    .withZone(java.time.ZoneId.systemDefault());            expiryString = formatter.format(nearestExpiringProduct.getPlanEndDate());        }        Instant startOfToday = java.time.LocalDate.now().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant();        List<TicketStatus> submittedStatuses = java.util.Arrays.asList(TicketStatus.SUBMITTED);        long totalSubmitted = ticketRepository.countByCustomerIdAndStatusIn(user.getId(), submittedStatuses);        long todaySubmitted = ticketRepository.countByCustomerIdAndStatusInAndCreatedAtAfter(user.getId(), submittedStatuses, startOfToday);        List<TicketStatus> resolvedStatuses = java.util.Arrays.asList(TicketStatus.RESOLVED, TicketStatus.CLOSED);        long totalResolved = ticketRepository.countByCustomerIdAndStatusIn(user.getId(), resolvedStatuses);        long todayResolved = ticketRepository.countByCustomerIdAndStatusInAndUpdatedAtAfter(user.getId(), resolvedStatuses, startOfToday);        return DashboardSummaryResponse.builder()                .purchasedHours(totalMins / 60)                .usedHours(usedMinsTotal / 60)                .usedMinutes(usedMinsTotal % 60)                .availableHours(displayAvailableMins / 60)                .availableMinutes(displayAvailableMins % 60)                .extraHours(extraMinsTotal / 60)                .supportPlanName(activeProduct != null ? activeProduct.getSupportPlan() : "No Active Plan")                // 👈 activeProduct ၏ Status ကိုလည်း Dynamic ဖြင့် ထုတ်ပေးမည်                .status(activeProduct != null ? getDynamicStatus(activeProduct).name() : "DISABLED")                .purchasedDate(activeProduct != null ? activeProduct.getPurchasedDate() : null)                .planEndDate(activeProduct != null ? activeProduct.getPlanEndDate() : null)                .slaHoursCard(DashboardSummaryResponse.SlaHoursCard.builder()                        .totalHours(totalMins / 60)                        .usedHours(usedMinsTotal / 60)                        .usedMinutes(usedMinsTotal % 60)                        .remainingHours(displayAvailableMins / 60)                        .remainingMinutes(displayAvailableMins % 60)                        .expiryDateText(expiryString)                        .daysRemaining(daysRemaining)                        .build())                .submittedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder()                        .totalCount((int) totalSubmitted)                        .todayCount((int) todaySubmitted)                        .build())                .resolvedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder()                        .totalCount((int) totalResolved)                        .todayCount((int) todayResolved)                        .build())                .activeProductCard(DashboardSummaryResponse.ProductStatCard.builder()                        .activeCount(activeProductCount)                        .totalCount(products.size())                        .expiryDateText(expiryString)                        .daysRemaining(daysRemaining)                        .build())                .build();    }    @Override    public MyProductDashboardResponse getMyProducts(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> clientProducts = clientProductRepository.findAllByUserId(user.getId());        int totalProducts = clientProducts.size();        // 👈 DB Status အစား Dynamic Status ကို အသုံးပြု၍ ရေတွက်မည်        int activeProducts = (int) clientProducts.stream()                .filter(cp -> {                    ProductStatus status = getDynamicStatus(cp);                    return status == ProductStatus.ACTIVE || status == ProductStatus.EXPIRING_SOON;                })                .count();        int totalSlaHours = clientProducts.stream()                .mapToInt(ClientProduct::getTotalMinutes)                .sum() / 60;        int extraUsageHours = clientProducts.stream()                .filter(cp -> cp.getAvailableMinutes() < 0)                .mapToInt(cp -> Math.abs(cp.getAvailableMinutes()))                .sum() / 60;        List<ClientProductResponse> productResponses = clientProducts.stream()                .map(this::mapToResponse)                .collect(Collectors.toList());        return MyProductDashboardResponse.builder()                .totalProducts(totalProducts)                .totalSlaHours(totalSlaHours)                .activeProducts(activeProducts)                .extraUsageHours(extraUsageHours)                .products(productResponses)                .build();    }    @Override    public ClientProductDetailResponse getClientProductDetails(Long clientProductId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        long daysRemaining = 0;        if (cp.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(Instant.now(), cp.getPlanEndDate());            if (daysRemaining < 0) daysRemaining = 0;        }        int totalMins = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;        int availMins = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;        int usedMinsTotal = availMins >= 0 ? totalMins - availMins : totalMins;        int remainMinsTotal = Math.max(availMins, 0);        int extraMinsTotal = availMins < 0 ? Math.abs(availMins) : 0;        ClientProductDetailResponse.SlaDetails slaDetails = ClientProductDetailResponse.SlaDetails.builder()                .totalSlaHours(totalMins / 60)                .remainingHours(remainMinsTotal / 60)                .remainingMinutes(remainMinsTotal % 60)                .usedHours(usedMinsTotal / 60)                .usedMinutes(usedMinsTotal % 60)                .extraHours(extraMinsTotal / 60)                .extraMinutes(extraMinsTotal % 60)                .daysRemaining(daysRemaining)                .planEndDate(cp.getPlanEndDate())                .build();        ClientProductDetailResponse.SystemMetadata metadata = ClientProductDetailResponse.SystemMetadata.builder()                .productType(cp.getProduct().getProductType())                .supportPlan(cp.getSupportPlan())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .build();        return ClientProductDetailResponse.builder()                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                // 👈 Dynamic Status ကို အသုံးပြုပါမည်                .status(getDynamicStatus(cp).name())                .slaDetails(slaDetails)                .metadata(metadata)                .build();    }    @Override    public List<ProductTicketDto> getProductRelatedTickets(Long clientProductId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        List<Ticket> tickets = ticketRepository.findAllByClientProductId(cp.getId());        return tickets.stream().map(t ->                ProductTicketDto.builder()                        .ticketId("DB-TK" + t.getId())                        .status(t.getStatus().name())                        .issueType(t.getIssueType().name())                        .assignedTeam(t.getDeveloper() != null ? t.getDeveloper().getFullName() : "Pending")                        .priority(t.getPriority() != null ? t.getPriority().name() : "Normal")                        .timeUsedMinutes(t.getSpentMinutes() != null ? t.getSpentMinutes() : 0)                        .build()        ).collect(Collectors.toList());    }    // 👈 [အသစ်ထပ်ဖြည့်ခြင်း] အချိန်တိုက်စစ်ပြီး Status ကို အလိုအလျောက် တွက်ပေးမည့် Method    private ProductStatus getDynamicStatus(ClientProduct cp) {        Instant now = Instant.now();        // ၁။ မစတင်ရသေးသော Plan (UPCOMING - အဟောင်းမကုန်သေး၍ စောင့်နေရခြင်း)        if (cp.getPlanStartDate() != null && cp.getPlanStartDate().isAfter(now)) {            return ProductStatus.UPCOMING;        }        // ၂။ သက်တမ်းကုန်သွားသော Plan (EXPIRED)        if (cp.getPlanEndDate() != null && cp.getPlanEndDate().isBefore(now)) {            return ProductStatus.EXPIRED;        }        // ၃။ သက်တမ်းကုန်ရန် ၇ ရက်လိုသော Plan (EXPIRING_SOON)        if (cp.getPlanEndDate() != null) {            long daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(now, cp.getPlanEndDate());            if (daysRemaining <= 7) {                return ProductStatus.EXPIRING_SOON;            }        }        // ၄။ ပုံမှန် အသုံးပြုနေဆဲ (ACTIVE)        return ProductStatus.ACTIVE;    }    private ClientProductResponse mapToResponse(ClientProduct cp) {        return ClientProductResponse.builder()                .id(cp.getId())                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .productType(cp.getProduct().getProductType())                .imageUrl(cp.getProduct().getImageUrl())                .supportPlan(cp.getSupportPlan())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .availableMinutes(cp.getAvailableMinutes())                .totalMinutes(cp.getTotalMinutes())                .status(getDynamicStatus(cp).name()) // 👈 Dynamic Status ကို အသုံးပြုပါမည်                .build();    }}